package com.ryanjei.orushio.pve.application;
import com.ryanjei.orushio.pve.core.*;import com.ryanjei.orushio.pve.domain.GameLaunchSettings;import com.ryanjei.orushio.pve.economy.*;import com.ryanjei.orushio.pve.map.*;import com.ryanjei.orushio.pve.pve.*;import java.util.*;
public final class Phase4GameReadinessValidator implements GameReadinessValidator{
 private final GameplaySettingsRepository gameplay;private final PveSettingsRepository pve;private final CoreSettingsRepository cores;private final ResourceMaterialValidator materials;
 public Phase4GameReadinessValidator(GameplaySettingsRepository gameplay,PveSettingsRepository pve,CoreSettingsRepository cores,ResourceMaterialValidator materials){this.gameplay=gameplay;this.pve=pve;this.cores=cores;this.materials=materials;}
 public List<String>missing(MapProfile map,GameLaunchSettings launch){LinkedHashSet<String>missing=new LinkedHashSet<>();long entryCount=map.enabledSetupMarkers(SetupMarkerType.FINAL_AREA_ENTRY).size(),destinationCount=map.enabledSetupMarkers(SetupMarkerType.FINAL_AREA_DESTINATION).size();for(String key:map.missingRequirements()){if(key.equals("marker:FINAL_AREA_DESTINATION")&&destinationCount>1)continue;missing.add(label(key)+"の設定がありません。");}if(entryCount>1)missing.add("最終エリア入口が1件だけ有効になっていません。");if(destinationCount>1)missing.add("最終エリア転送先が1件だけ有効になっていません。");if(map.areas().getOrDefault("resourceZones",List.of()).isEmpty())missing.add("資源採取エリアの設定がありません。");try{GameplaySettings value=gameplay.load(map.mapId().value());try{FarmEconomyLifecycleStep.validateConfiguration(map,value,materials);}catch(RuntimeException failure){if(map.areas().getOrDefault("resourceZones",List.of()).stream().anyMatch(region->value.resourceZones().stream().noneMatch(zone->zone.region().equals(region))))missing.add("資源採取エリアのPoint・再生成設定がありません。");if(missing.stream().noneMatch(text->text.contains("資源採取")||text.contains("ショップ")))missing.add("資源・ショップ設定に不整合があります。");}}catch(RuntimeException failure){missing.add("資源・ショップ設定を読み込めません。");}try{PveSettings value=pve.load(map.mapId().value());try{PveLifecycleStep.validateConfiguration(map,value);}catch(RuntimeException failure){missing.add("敵出現エリアの敵・出現間隔設定がありません。");}}catch(RuntimeException failure){missing.add("敵出現設定を読み込めません。");}try{cores.load(map.mapId().value());}catch(RuntimeException failure){missing.add("通常コア・最終コアのHP設定がありません。");}if(map.enabledSetupMarkers(SetupMarkerType.NORMAL_CORE).size()<launch.resolvedRequiredNormalCores())missing.add("攻略に必要な有効な通常コア候補地点が不足しています。");return List.copyOf(missing);}
 private static String label(String key){if(key.startsWith("marker:")){String type=key.substring(7);if(type.equals("SHOP"))return "ショップ地点";try{return SetupMarkerType.valueOf(type).label();}catch(RuntimeException ignored){return "設定地点";}}try{return MapFieldCatalog.label(key);}catch(RuntimeException ignored){return "マップ必須項目";}}
}
